import 'dart:convert';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitOrLoss});
}

// Function to calculate average profit or loss for a given list of transactions
double calculateAverage(List<Transaction> transactions) {
  double totalProfitOrLoss = 0;
  int count = 0;
  for (final Transaction transaction in transactions) {
    totalProfitOrLoss += transaction.profitOrLoss;
    count++;
  }
  return totalProfitOrLoss / count;
}

// Function to find the top n coins with highest average profit
List<String> findTopCoinsWithHighestAvgProfit(List<Transaction> transactions, int n) {
  Map<String, List<Transaction>> groupedTransactions = {};
  for (final Transaction transaction in transactions) {
    if (!groupedTransactions.containsKey(transaction.coinName)) {
      groupedTransactions[transaction.coinName] = [];
    }
    groupedTransactions[transaction.coinName].add(transaction);
  }

  // Calculate average profit for each group
  List<MapEntry<String, double>> avgProfits = [];
  for (final String coinName in groupedTransactions.keys) {
    avgProfits.add(MapEntry(coinName, calculateAverage(groupedTransactions[coinName])));
  }

  // Sort by average profit and take first n entries
  avgProfits.sort((a, b) => b.value.compareTo(a.value));
  List<String> result = [];
  for (int I = 0; I < n && I < avgProfits.length; i++) {
    result.add(avgProfits[i].key);
  }
  return result;
}

