Here's how you could implement this in Swift:

```swift
let misusedHomophones = ["is": "are", "weigh": "weight", "no": "know", "see": "see", "good": "good", "true": "true", "write": "right"]

let passage = """
Their is know weigh too no if yew see summing and it seams too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't no the write weigh two do it. Weather or not yew no the difference between there, their, and they're, yew can't denigh that its a common mistake. But can yew correct it programmatically using Swift?
"""

let correctedPassage = correctHomophones(passage: passage, misusedHomophones: misusedHomophones)
print(correctedPassage)

// Function to replace misused homophones
func correctHomophones(passage: String, misusedHomophones: [String: String]) -> String {
    let words = passage.components(separatedBy: .whitespacesAndNewlines)
    var correctedWords = [String]()
    for word in words {
        let parts = word.components(separatedBy: " ")
        for (index, part) in parts.enumerated() {
            if let replacement = misusedHomophones[part] {
                parts[index] = replacement
            }
        }
        correctedWords.append(parts.joined(separator: " "))
    }
    return correctedWords.joined(separator: " ")
}
```

