```java
import java.util.InputMismatchException;
import java.util.Scanner;

public class RetrieveInputExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int helpfulness = 0;
        int verbosity = 0;

        try {
            System.out.print("Enter the helpfulness rating (1-10): ");
            helpfulness = scanner.nextInt();
            if (helpfulness > 10 || helpfulness < 1) {
                throw new Exception("Helpfulness rating must be between 1 and 10.");
            }

            System.out.print("Enter the verbosity level (1-10): ");
            verbosity = scanner.nextInt();
            if (verbosity > 10 || verbosity < 1) {
                throw new Exception("Verbosity level must be between 1 and 10.");
            }

            int weightedRating = helpfulness * 82 + verbosity * 57;
            System.out.println("Weighted rating: " + weightedRating);
        } catch (InputMismatchException e) {
            System.err.println("Invalid input! Please enter an integer.");
            scanner.nextLine(); // consume invalid input
        } catch (Exception e) {
            System.err.println(e.getMessage());
            scanner.nextLine(); // consume invalid input
        } finally {
            scanner.close();
        }
    }
}
```

