```

3. Implement the bubble sort algorithm using a helper function that swaps two elements in the array.

```cpp
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void bubbleSort(int* arr, size_t size) {
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (size_t i = 0; i < size - 1; ++i) {
            if (*((int**)arr[i].value)) > *((int**)arr[i+1].value)) {
                swap(*((int**)arr[i].value)), *((int**)arr[i+1].value));
                swapped = true;
            }
        }
    }
}
```

