```javascript
function generateNotificationMessage(notifObj) {
  let weightedRating = 0;
  let bestMessage = "";
  for (const [notifType, notifArr] of Object.entries(notifObj)) {
    let helpfulnessScore = 0;
    let verbosityScore = 0;
    for (const notification of notifArr) {
      helpfulnessScore += notification.helpfulness;
      verbosityScore += notification.text.length;
    }
    const messageWeightedRating = helpfulnessScore * 82 + verbosityScore * 57;
    if (messageWeightedRating > weightedRating && messageWeightedRating !== Infinity) {
      weightedRating = messageWeightedRating;
      bestMessage = `{${notifType}}}${notificationArr[0].text}`;
    }
  }
  return bestMessage;
}
```

